e15b510d","home_team_id":"2368a5c2-7a91-484a-b201-fde870c85690","kickoff_time":"20:20:00","round_number":2,"schedule_status":"scheduled","schedule_version":1,"publication_state":"published","competition_season_id":"62ce7ec9-459e-4acf-bec5-c6734a3199ef"}},{"home":"AFG","away":"King ADL","home_team_id":"3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff","away_team_id":"57b0b3f9-24a5-4ea7-9e1b-fd3faa90891c","home_score":5,"away_score":4,"kickoff_time":"21:00:00","court":2,"id":"d643c4f5-4a21-56b7-a825-09b6cb13e564","expected_version":1,"original":{"id":"d643c4f5-4a21-56b7-a825-09b6cb13e564","court":1,"stage":"regular_season","legacy_id":"mon-2026-s2-r2-2100-c1","created_at":"2026-10-15T08:58:03.138018+00:00","match_date":"2026-10-19","updated_at":"2026-10-15T08:58:03.138018+00:00","public_note":null,"round_label":"Round 2","away_team_id":"3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff","home_team_id":"57b0b3f9-24a5-4ea7-9e1b-fd3faa90891c","kickoff_time":"21:00:00","round_number":2,"schedule_status":"scheduled","schedule_version":1,"publication_state":"published","competition_season_id":"62ce7ec9-459e-4acf-bec5-c6734a3199ef"}}]'::jsonb)
