CREATE TEMP TABLE oct19_changed ON COMMIT DROP AS select p.id from oct19_plan p join public.fixtures f on f.id=p.id
 WHERE row(f.home_team_id,f.away_team_id,f.kickoff_time,f.court) IS DISTINCT FROM row(p.home_team_id,p.away_team_id,p.kickoff_time,p.court);
DO $$ BEGIN
 IF (select md5(jsonb_agg(to_jsonb(f) order by id)::text) from public.fixtures f)<>'112e49816a66ac36d720945fd87c9227' OR (select md5(jsonb_agg(to_jsonb(r) order by id)::text) from public.result_versions r)<>'fb8afcb4c1e8fe901add297074502ab0' THEN RAISE EXCEPTION 'Production baseline changed; review required'; END IF;
 IF (select count(*) from oct19_plan)<>8 OR (select count(distinct id) from oct19_plan)<>8 OR (select count(*) from oct19_changed)<>7 THEN RAISE EXCEPTION 'Wrong fixture plan'; END IF;
 IF (select count(distinct team_id) from (select home_team_id team_id from oct19_plan union all select away_team_id from oct19_plan) t)<>16 OR (select count(distinct(kickoff_time,court)) from oct19_plan)<>8 THEN RAISE EXCEPTION 'Team or court/time collision'; END IF;
 IF NOT EXISTS(select 1 from public.competition_seasons where id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' and lifecycle='active' and publication_state='published') THEN RAISE EXCEPTION 'Monday edition changed'; END IF;
 IF (select count(*) from public.fixtures where competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' and round_number=2)<>8 THEN RAISE EXCEPTION 'Round 2 fixture count changed'; END IF;
 IF EXISTS(select 1 from oct19_plan p left join public.fixtures f on f.id=p.id where f.id is null or to_jsonb(f) IS DISTINCT FROM p.original or f.competition_season_id<>'62ce7ec9-459e-4acf-bec5-c6734a3199ef' or f.round_number<>2 or f.match_date<>'2026-10-19' or f.stage<>'regular_season' or f.publication_state<>'published' or f.schedule_status<>'scheduled' or exists(select 1 from public.result_versions r where r.fixture_id=f.id)) THEN RAISE EXCEPTION 'Fixture changed or already has a result; stop'; END IF;
 IF EXISTS(select 1 from oct19_plan p left join public.teams h on h.id=p.home_team_id left join public.teams a on a.id=p.away_team_id where h.name IS DISTINCT FROM p.home or a.name IS DISTINCT FROM p.away or h.competition_season_id<>'62ce7ec9-459e-4acf-bec5-c6734a3199ef' or a.competition_season_id<>'62ce7ec9-459e-4acf-bec5-c6734a3199ef' or h.status<>'active' or a.status<>'active' or p.home_score<0 or p.away_score<0) THEN RAISE EXCEPTION 'Wrong team identities or scores'; END IF;
END $$;
CREATE TEMP TABLE oct19_protected ON COMMIT DROP AS
select 'other_fixtures'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(f) as row from public.fixtures f where not exists(select 1 from oct19_changed c where c.id=f.id)) protected_rows) hash
UNION ALL
select 'previous_results'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(r) as row from public.result_versions r where not exists(select 1 from oct19_plan p where p.id=r.fixture_id)) protected_rows) hash
UNION ALL
select 'teams'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(t) as row from public.teams t) protected_rows) hash
UNION ALL
select 'notes'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(n) as row from public.team_fixture_notes n) protected_rows) hash
UNION ALL
select 'preferences'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(p) as row from public.team_kickoff_preferences p) protected_rows) hash
UNION ALL
select 'adjustments'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.standing_adjustments a) protected_rows) hash
UNION ALL
select 'editions'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(c) as row from public.competition_seasons c) protected_rows) hash
UNION ALL
select 'seasons'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(s) as row from public.seasons s) protected_rows) hash
UNION ALL
select 'old_audit'::text kind,(select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.admin_audit_log a where transaction_id<>txid_current()) protected_rows) hash;
-- Free only changed slots within this transaction. MVCC preserves old public state until commit.
UPDATE public.fixtures f SET publication_state='draft' FROM oct19_changed c WHERE f.id=c.id;
UPDATE public.fixtures f SET home_team_id=p.home_team_id,away_team_id=p.away_team_id,kickoff_time=p.kickoff_time,court=p.court,publication_state='published'
 FROM oct19_plan p JOIN oct19_changed c ON c.id=p.id WHERE f.id=p.id;
-- Existing validation/audit triggers remain enabled; published_at and authorship are set by their normal trigger.
INSERT INTO public.result_versions(fixture_id,revision,status,home_score,away_score)
 SELECT id,1,'published',home_score,away_score FROM oct19_plan;
DO $$ BEGIN
 IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(f) as row from public.fixtures f where not exists(select 1 from oct19_changed c where c.id=f.id)) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='other_fixtures') THEN RAISE EXCEPTION 'Protected other_fixtures changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(r) as row from public.result_versions r where not exists(select 1 from oct19_plan p where p.id=r.fixture_id)) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='previous_results') THEN RAISE EXCEPTION 'Protected previous_results changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(t) as row from public.teams t) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='teams') THEN RAISE EXCEPTION 'Protected teams changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(n) as row from public.team_fixture_notes n) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='notes') THEN RAISE EXCEPTION 'Protected notes changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(p) as row from public.team_kickoff_preferences p) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='preferences') THEN RAISE EXCEPTION 'Protected preferences changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.standing_adjustments a) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='adjustments') THEN RAISE EXCEPTION 'Protected adjustments changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(c) as row from public.competition_seasons c) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='editions') THEN RAISE EXCEPTION 'Protected editions changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(s) as row from public.seasons s) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='seasons') THEN RAISE EXCEPTION 'Protected seasons changed; rollback'; END IF;
IF (select md5(coalesce(jsonb_agg(row order by row::text)::text,'[]')) from (select to_jsonb(a) as row from public.admin_audit_log a where transaction_id<>txid_current()) protected_rows) IS DISTINCT FROM (select hash from oct19_protected where kind='old_audit') THEN RAISE EXCEPTION 'Protected old_audit changed; rollback'; END IF;
 IF (select count(*) from public.result_versions r join oct19_plan p on p.id=r.fixture_id where r.status='published')<>8 THEN RAISE EXCEPTION 'Expected eight published results'; END IF;
 IF EXISTS(select 1 from oct19_plan p join public.fixtures f on f.id=p.id join public.result_versions r on r.fixture_id=f.id where
 row(f.home_team_id,f.away_team_id,f.kickoff_time,f.court) IS DISTINCT FROM row(p.home_team_id,p.away_team_id,p.kickoff_time,p.court)
 or f.publication_state<>'published' or f.schedule_version<>p.expected_version+case when exists(select 1 from oct19_changed c where c.id=p.id) then 2 else 0 end
 or r.status<>'published' or r.revision<>1 or r.home_score<>p.home_score or r.away_score<>p.away_score or r.forfeit_side is not null or r.published_at is null) THEN RAISE EXCEPTION 'Published fixture/result mismatch'; END IF;
 IF EXISTS(select 1 from oct19_plan p join public.fixtures f on f.id=p.id where (to_jsonb(f)-'home_team_id'-'away_team_id'-'kickoff_time'-'court'-'publication_state'-'schedule_version'-'updated_at') IS DISTINCT FROM (p.original-'home_team_id'-'away_team_id'-'kickoff_time'-'court'-'publication_state'-'schedule_version'-'updated_at')) THEN RAISE EXCEPTION 'Unrequested fixture metadata change'; END IF;
 IF (select count(*) from public.admin_audit_log where transaction_id=txid_current())<>22 THEN RAISE EXCEPTION 'Expected 22 audited changes'; END IF;
END $$;
COMMIT;
SELECT f.id,f.match_date,f.kickoff_time,f.court,h.name home_team,r.home_score,r.away_score,a.name away_team,r.id result_id
 FROM public.fixtures f JOIN public.teams h ON h.id=f.home_team_id JOIN public.teams a ON a.id=f.away_team_id JOIN public.result_versions r ON r.fixture_id=f.id AND r.status='published'
 WHERE f.competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND f.round_number=2 ORDER BY f.kickoff_time,f.court;
